#!/usr/bin/env bash
set -Eeuo pipefail

REPO_ROOT="${1:-$HOME/Linuxa33}"
TMP="$(mktemp -d)"
cleanup() { rm -rf "$TMP"; }
trap cleanup EXIT INT TERM HUP

for command in python3 base64 gzip bash git mktemp rm; do
    command -v "$command" >/dev/null 2>&1 || {
        echo "Missing required host command: $command" >&2
        exit 1
    }
done

cat <<'PATCH_B64' | base64 -d | gzip -d > "$TMP/apply.py"

PATCH_B64
cat <<'AUDIT_B64' | base64 -d | gzip -d > "$TMP/audit.sh"

AUDIT_B64
chmod 700 "$TMP/apply.py" "$TMP/audit.sh"

python3 "$TMP/apply.py" "$REPO_ROOT"
REPO_ROOT="$REPO_ROOT" bash "$TMP/audit.sh"
